class Solution {
public:
    int minimumCoins(vector<int>& prices) {
        int n = prices.size();
        vector<int> f(n + 1);
        deque<int> dq{{0}};
        auto g = [&](int j) { return f[j] + prices[j]; };
        for (int i = 1; i <= n; ++i) {
            int lo = max(0, (i + 1) / 2 - 1);
            while (dq.front() < lo) dq.pop_front();
            f[i] = g(dq.front());
            int c = i - 1;
            while (!dq.empty() && g(dq.back()) >= g(c)) dq.pop_back();
            dq.push_back(c);
        }
        return f[n];
    }
};

