class Solution:
    def minimumCoins(self, prices):
        n = len(prices)
        INF = float('inf')
        size = 1
        while size < n: size *= 2
        tree = [INF] * (2 * size)
        def upd(p, v):
            p += size; tree[p] = v; p >>= 1
            while p:
                tree[p] = min(tree[2*p], tree[2*p+1]); p >>= 1
        def qry(l, r):
            res = INF; l += size; r += size + 1
            while l < r:
                if l & 1: res = min(res, tree[l]); l += 1
                if r & 1: r -= 1; res = min(res, tree[r])
                l >>= 1; r >>= 1
            return res
        f = [0] * (n + 1)
        upd(0, prices[0])
        for i in range(1, n + 1):
            lo = max(0, (i + 1) // 2 - 1)
            f[i] = qry(lo, i - 1)
            if i - 1 < n:
                upd(i - 1, f[i - 1] + prices[i - 1])
        return f[n]

