class Solution {
public:
    int minimumCoins(vector<int>& prices) {
        int n = prices.size();
        const int INF = INT_MAX;
        int sz = 1; while (sz < n) sz <<= 1;
        vector<int> tree(2 * sz, INF);
        auto upd = [&](int p, int v) {
            p += sz; tree[p] = v;
            for (p >>= 1; p; p >>= 1) tree[p] = min(tree[2*p], tree[2*p+1]);
        };
        auto qry = [&](int l, int r) {
            int res = INF;
            for (l += sz, r += sz + 1; l < r; l >>= 1, r >>= 1) {
                if (l & 1) res = min(res, tree[l++]);
                if (r & 1) res = min(res, tree[--r]);
            }
            return res;
        };
        vector<int> f(n + 1);
        upd(0, prices[0]);
        for (int i = 1; i <= n; ++i) {
            int lo = max(0, (i + 1) / 2 - 1);
            f[i] = qry(lo, i - 1);
            upd(i - 1, f[i - 1] + prices[i - 1]);
        }
        return f[n];
    }
};

