class Solution {
    public int minimumCoins(int[] prices) {
        int n = prices.length;
        final int INF = Integer.MAX_VALUE;
        int sz = 1; while (sz < n) sz <<= 1;
        int[] tree = new int[2 * sz];
        java.util.Arrays.fill(tree, INF);
        java.util.function.BiConsumer<Integer,Integer> upd = (pp, v) -> {
            int p = pp + sz; tree[p] = v;
            for (p >>= 1; p > 0; p >>= 1) tree[p] = Math.min(tree[2*p], tree[2*p+1]);
        };
        upd.accept(0, prices[0]);
        int[] f = new int[n + 1];
        for (int i = 1; i <= n; ++i) {
            int lo = Math.max(0, (i + 1) / 2 - 1);
            int l = lo + sz, r = i - 1 + sz, res = INF;
            while (l <= r) {
                if ((l & 1) == 1) res = Math.min(res, tree[l++]);
                if ((r & 1) == 0) res = Math.min(res, tree[r--]);
                l >>= 1; r >>= 1;
            }
            f[i] = res;
            upd.accept(i - 1, f[i - 1] + prices[i - 1]);
        }
        return f[n];
    }
}

